/**
 * @file main.c
 * @brief Minimal PN532 I2C example for a CubeMX-generated STM32 project.
 *
 * Copy the marked application code into the corresponding USER CODE sections
 * of the main.c generated by STM32CubeMX. Clock, GPIO and I2C setup remain
 * project-specific and are generated by CubeMX.
 */

#include "main.h"
#include "pn532.h"

I2C_HandleTypeDef hi2c1;

static void SystemClock_Config(void);
static void MX_GPIO_Init(void);
static void MX_I2C1_Init(void);

int main(void)
{
  PN532_Handle nfc;
  PN532_FirmwareInfo firmware;
  PN532_Target target;
  PN532_Status status;

  HAL_Init();
  SystemClock_Config();
  MX_GPIO_Init();
  MX_I2C1_Init();

  status = PN532_Init(&nfc, &hi2c1);
  if (status == PN532_OK)
  {
    status = PN532_GetFirmwareVersion(&nfc, &firmware);
  }
  if (status == PN532_OK)
  {
    status = PN532_ConfigureReader(&nfc);
  }
  if (status != PN532_OK)
  {
    Error_Handler();
  }

  while (1)
  {
    status = PN532_ReadPassiveTarget(&nfc, &target);
    if (status == PN532_OK)
    {
      /* Inspect target.uid and target.uid_length in the debugger. */
      volatile uint8_t uid_length = target.uid_length;
      (void)uid_length;
    }

    HAL_Delay(250U);
  }
}

/* Implemented by STM32CubeMX in the generated project. */
static void SystemClock_Config(void) { /* CubeMX-generated code */ }
static void MX_GPIO_Init(void)       { /* CubeMX-generated code */ }
static void MX_I2C1_Init(void)       { /* CubeMX-generated code */ }
